// Generic Debug Representation Function
template <typename T>
std::string debug_rep(const T& t) {
    std::ostringstream oss;
    oss << t;
    return oss.str();
}

// Specialization for String Literals
std::string debug_rep(const std::string& s) {
    return "\"" + s + "\"";
}

// Specialization for Pointers (Value or nullptr)
template <typename T>
std::string debug_rep(T* p) {
    std::ostringstream oss;
    oss << "pointer: " << p;
    if (p) oss << " -> " << debug_rep(*p);
    return oss.str();
}
